export function authoredMessageKey(value: string): MessageKey | undefined {
  return Object.hasOwn(zh, value) ? value as MessageKey : Object.hasOwn(authoredKeys, value) ? authoredKeys[value] : undefined;
}
export function formatMessage<K extends MessageKey>(locale: Locale, key: K, ...args: MessageArgs<K>): string {
  if (!Object.hasOwn(resources, locale) || !Object.hasOwn(resources[locale], key)) throw new Error('Unknown localization resource: ' + locale + '/' + key);
  const params = args[0] as Record<string, string | number> | undefined;
  const expected = parameterNames[key] ?? [];
  if (expected.length !== Object.keys(params ?? {}).length || expected.some(name => !Object.hasOwn(params ?? {}, name))) throw new Error('Invalid localization parameters: ' + key);
  return resources[locale][key].replace(/\{([a-zA-Z][\w]*)\}/g, (_, name: string) => String(params![name]));
}
